// Real-text preview generated by TestRealBookLayout. No production mutation or AI.
const assert=require('node:assert/strict'),fs=require('node:fs');
const {chromium}=require(process.env.PLAYWRIGHT_MODULE||'playwright');
const base=process.env.TEST_BASE_URL||'http://localhost:4321';
(async()=>{
 const cards=JSON.parse(fs.readFileSync(process.env.CARD_TEST_PREVIEW,'utf8'));
 const browser=await chromium.launch({...(process.env.PLAYWRIGHT_EXECUTABLE?{executablePath:process.env.PLAYWRIGHT_EXECUTABLE}:{}),args:['--no-sandbox']});
 const mr=cards.find(c=>c.kind==='text'&&c.content.includes('Mr. Bingley')&&c.parts.length>1&&(c.content.match(/\n/g)||[]).length<=4);
 assert(mr,'missing cross-source Mr. Bingley regression');
 const samples=[...new Set([2,mr.idx,...cards.filter(c=>c.kind==='text'&&c.content.includes('\n\n')).slice(0,8).map(c=>c.idx),...cards.filter(c=>c.kind==='text'&&c.content.includes('Every lingering')).map(c=>c.idx)])];
 for(const [width,height]of [[320,568],[390,600],[1280,720]]){
  const ctx=await browser.newContext({viewport:{width,height},serviceWorkers:'block'}),page=await ctx.newPage(),errors=[];
  page.on('pageerror',e=>errors.push(e.message));
  await page.route('**/v1/**',route=>{
   const url=new URL(route.request().url());let body={};
   if(url.pathname.endsWith('/cards')){const from=Number(url.searchParams.get('card_from')||0),limit=Number(url.searchParams.get('limit')||12);body={pages:cards.slice(from,from+limit),page_count:cards.length};}
   else if(url.pathname==='/v1/me')body={user:{tier:'pro'}};
   else if(url.pathname.startsWith('/v1/books/'))body={book:{title:'Pride and Prejudice',author:'Jane Austen'}};
   else if(url.pathname==='/v1/card-reads')body={streak_extended:false};
   return route.fulfill({json:body});
  });
  for(const idx of samples){
   await page.goto(base+'/read/pride-and-prejudice/?card='+idx,{waitUntil:'networkidle'});
   await page.waitForSelector('[data-body]');await page.waitForTimeout(80);
   let collected='',parts=0;
   while(true){
    const geometry=await page.locator('[data-body]').evaluate(el=>{
     const r=el.getBoundingClientRect(),article=el.closest('.page'),a=article.getBoundingClientRect(),style=getComputedStyle(article);
     return{text:el.textContent,top:r.top,bottom:r.bottom,allowedTop:a.top+parseFloat(style.paddingTop),allowedBottom:a.bottom-parseFloat(style.paddingBottom),font:parseFloat(getComputedStyle(el).fontSize),overflow:getComputedStyle(el).overflowY};
    });
    collected+=geometry.text;parts++;
    assert(geometry.top>=geometry.allowedTop-1&&geometry.bottom<=geometry.allowedBottom+1,`real card ${idx} does not fit at ${width}: ${JSON.stringify(geometry)}`);
    assert(geometry.font>=16,'normal font shrunk');assert.equal(geometry.overflow,'visible');
    const num=await page.locator('.page-num').innerText(),match=num.match(/part (\d+)\/(\d+)/);
    if(!match||match[1]===match[2])break;
    await page.getByRole('button',{name:'Next card',exact:true}).click();await page.waitForTimeout(40);
    assert(parts<30,'continuation loop');
   }
   assert.equal(collected,cards[idx].content,'lost/duplicated real text in continuations');
  }
  await page.goto(base+'/read/pride-and-prejudice/?card='+mr.idx,{waitUntil:'networkidle'});await page.waitForTimeout(120);
  assert((await page.locator('[data-body]').innerText()).includes('Mr. Bingley'),'abbreviation gap returned');
  await page.mouse.wheel(0,700);await page.waitForTimeout(80);
  assert.equal(await page.locator('.feed').evaluate(el=>el.scrollTop),0,'card feed scrolls');
  assert.equal(await page.locator('[data-body]').evaluate(el=>el.scrollTop),0,'text scrolls');
  assert.equal(await page.evaluate(()=>window.scrollY),0,'document scrolls');
  assert.deepEqual(errors,[]);
  if(process.env.SCREENSHOT_DIR)await page.screenshot({path:`${process.env.SCREENSHOT_DIR}/rechunk-${width}.png`});
  console.log(`${width}×${height}: ${samples.length} real-text samples, every continuation intact and readable, no scrolling, Mr. Bingley repaired`);
  await ctx.close();
 }
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
